import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import './Resources.css';

const ResourcesPage = () => {
  // --- Navigation & Menu State ---
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  
  // --- MEGA MENU STATES ---
  const [activeCategory, setActiveCategory] = useState('Air Quality');
  const [isMegaMenuOpen, setIsMegaMenuOpen] = useState(false);

  // --- DATA: Publications ---
  const publications = [
    {
      type: 'Conference Paper',
      title: 'Comparative Analysis of RNN models for Air Pollution Forecasting',
      venue: 'ICICDS-2025',
      status: 'Published'
    },
    {
      type: 'Research Paper',
      title: 'A Comparative Analysis of Conventional Methods for Sensor-Driven Spatial Interpolation for Air Quality Monitoring',
      venue: 'Engineering, Technology & Applied Science Research',
      status: 'Communicated'
    },
    {
      type: 'Conference Paper',
      title: 'AI-Based Environmental Pollution Monitoring with Personalized Health Risk Assessment',
      venue: 'ICSSAI-2025 (Kolkata)',
      status: 'Accepted'
    }
  ];

  // --- DATA: Patents ---
  const patent = {
    title: 'Artificial Intelligence Integrated Water Level Monitoring Solution with an Associated Alert for Floods',
    appNumber: '202441079490',
    filingDate: 'October 25, 2024',
    status: 'Filed with INDIA Patent Office'
  };

  // --- DATA: Training / Manpower ---
  const trainingEvents = [
    { title: 'IoT Impression – Arduino & Raspberry pi', type: 'Hands-on-Workshop', duration: '1 Day', date: 'March 19, 2025', participants: 40 },
    { title: 'Electronic Prototyping & IoT Solutions', type: 'Summer Internship', duration: '15 Days', date: 'June 2-24, 2025', participants: '49 Students' },
    { title: 'IoT Powered Robotics: ESP8266 to RPi', type: 'Workshop', duration: '3 Days', date: 'June 25-27, 2025', participants: 37 },
    { title: 'IoT Prototyping and PCB Design', type: 'Value Added Course', duration: '4 Days', date: 'July 1-4, 2025', participants: 63 },
    { title: 'Edge Hardware Design – PCB Workshop', type: 'Workshop', duration: '10 Days', date: 'July 7-17, 2025', participants: 84 },
    { title: 'Embedded System and Digital Design', type: 'Value Added Course', duration: '5 Days', date: 'July 16-21, 2025', participants: 51 },
    { title: 'Raspberry Pi Workshop', type: 'Hands-on-Workshop', duration: '1 Day', date: 'September 11, 2025', participants: 63 }
  ];

  // --- DATA: Objectives ---
  const objectives = [
    "Develop intelligent sensor modules for pollution monitoring.",
    "Validate smart water level monitoring with flood alerts.",
    "Create digital systems for water level distribution.",
    "Build a startup & skill development ecosystem.",
    "Develop Explainable AI (XAI) analysis software for IoT."
  ];

  // --- MEGA MENU DATA ---
  const productMenuData = {
    'Air Quality': {
      title: 'Air Quality Monitoring',
      description: 'Precision sensors for indoor and outdoor environments.',
      items: [
        { name: 'AQMS Indoor', image: '/sensor_modules/aqms-station1.jpg', link: '/product-details/indoor-monitor' },
        { name: 'AQMS Outdoor', image: '/sensor_modules/aqi1.jpeg', link: '/product-details/outdoor-station' },
        { name: 'Gas Sensors', image: '/sensor_modules/aqi-indoor.jpeg', link: '/product-details/gas-sensors' }
      ]
    },
    'Water Solutions': {
      title: 'Water Management',
      description: 'Flood alerts and distribution logic.',
      items: [
        { name: 'Predictive Flood Alert', image: '/sensor_modules/river1.jpg', link: '/product-details/flood-alert' },
        { name: 'Digital Flow Meter', image: '/sensor_modules/distribution.jpeg', link: '/product-details/distribution-net' }
      ]
    },
    'Weather': {
      title: 'Weather Stations',
      description: 'Hyper-local weather data collection.',
      items: [
        { name: 'AWS Station', image: '/sensor_modules/weather.jpg', link: '/product-details/weather-station' },
      ]
    },
    'Training': {
      title: 'Skill Development',
      description: 'Kits and workshops for students.',
      items: [
        { name: 'IoT Workshops', image: '/sensor_modules/skill.jpg', link: '/product-details/iot-training' },
        { name: 'PCB Design', image: 'https://images.unsplash.com/photo-1517048676732-d65bc937f952?w=400', link: '/product-details/pcb-workshop' }
      ]
    }
  };

  // --- Resource Logic ---
  const [brochures, setBrochures] = useState([]);
  const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://127.0.0.1:8000';

  useEffect(() => {
    const fetchBrochures = async () => {
      try {
        const response = await fetch(`${API_BASE_URL}/api/brochures/`);
        const data = await response.json();
        const brochureArray = data.results || data;

        if (brochureArray && brochureArray.length > 0) {
          const formatted = brochureArray.map(b => ({
            title: b.title,
            description: b.description,
            url: b.file.startsWith('http') ? b.file : `${API_BASE_URL}${b.file}`,
            category: b.category || 'General'
          }));
          setBrochures(formatted);
        }
      } catch (error) {
        console.error('Error fetching brochures:', error);
      }
    };
    fetchBrochures();
  }, [API_BASE_URL]);

  return (
    <div className="resources-page-container">
      
      {/* ===================================================== */}
      {/* HEADER (Glassmorphism)                                */}
      {/* ===================================================== */}
      <header className="aiiot-header-local">
         <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '0 1.5rem' }}>
           <nav style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', height: '5rem' }}>
             
             {/* LOGO */}
             <Link to="/" style={{ display: 'flex', alignItems: 'center', gap: '1rem', textDecoration: 'none' }}>
               <div className="logo-box">
                 <img src="/logo/logo.png" alt="Adi Shankara Institute" style={{ height: '100%', width: 'auto' }} />
               </div>
               <div style={{ display: 'flex', flexDirection: 'column' }}>
                 <span style={{ fontSize: '1.25rem', fontWeight: 800, color: '#0f172a', lineHeight: 1.2, letterSpacing: '-0.02em' }}>AI-IoT Innovations</span>
                 <span style={{ fontSize: '0.75rem', color: '#64748b', fontWeight: 600 }}>Adi Shankara Engineering Institute</span>
               </div>
             </Link>
 
             {/* DESKTOP NAV */}
             <div className="desktop-nav" style={{ display: 'flex', alignItems: 'center' }}>
               <a href="https://aiiot.it.com/project/intelligent-sensor" className="nav-link">Solutions</a>
               <Link to="/resources" className="nav-link" style={{ color: '#2563eb' }}>Resources</Link>
               
               {/* MEGA MENU TRIGGER */}
               <div 
                 className="mega-menu-wrapper"
                 style={{ position: 'relative', marginRight: '2rem' }}
                 onMouseEnter={() => setIsMegaMenuOpen(true)}
                 onMouseLeave={() => setIsMegaMenuOpen(false)}
               >
                 <span className="nav-link" style={{ cursor: 'pointer' }}>Products ▾</span>
                 
                 {/* Mega Menu Dropdown */}
                 {isMegaMenuOpen && (
                   <div style={{ 
                       position: 'absolute', top: '3rem', right: '-10rem', 
                       background: 'white', border: '1px solid #e2e8f0', borderRadius: '1rem', 
                       boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1)', padding: '1.5rem', 
                       display: 'flex', width: '600px', gap: '1.5rem', zIndex: 2000 
                   }}>
                     <div style={{ width: '150px', borderRight: '1px solid #f1f5f9' }}>
                       {Object.keys(productMenuData).map((key) => (
                         <div 
                            key={key}
                            style={{ padding: '0.5rem 0', cursor: 'pointer', fontWeight: activeCategory === key ? 700 : 500, color: activeCategory === key ? '#2563eb' : '#64748b' }}
                            onMouseEnter={() => setActiveCategory(key)}
                         >
                           {key}
                         </div>
                       ))}
                     </div>
                     <div style={{ flex: 1 }}>
                        <h4 style={{ margin: '0 0 0.5rem 0', color: '#0f172a' }}>{productMenuData[activeCategory].title}</h4>
                        <p style={{ fontSize: '0.85rem', color: '#64748b', marginBottom: '1rem' }}>{productMenuData[activeCategory].description}</p>
                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
                           {productMenuData[activeCategory].items.map((item, idx) => (
                             <Link to={item.link} key={idx} style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', textDecoration: 'none', color: '#334155', fontSize: '0.9rem', fontWeight: 500 }}>
                                <div style={{ width: '40px', height: '40px', borderRadius: '6px', overflow: 'hidden', background: '#f1f5f9' }}>
                                    <img src={item.image} alt={item.name} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                                </div>
                                {item.name}
                             </Link>
                           ))}
                        </div>
                     </div>
                   </div>
                 )}
               </div>

               <a href="#contact" className="nav-btn-primary">Get in Touch</a>
             </div>
 
             {/* MOBILE HAMBURGER */}
             <button className="mobile-nav-toggle" onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
               {isMobileMenuOpen ? '✕' : '☰'}
             </button>
           </nav>
         </div>
      </header>

      {/* ===================================================== */}
      {/* MAIN CONTENT                                          */}
      {/* ===================================================== */}
      <div className="resources-content-wrapper">
        
        {/* 1. HERO SECTION */}
        <section className="resources-hero-section">
          <span className="hero-badge">Center of Excellence</span>
          <h1 className="page-title">AI-IoT Innovation Hub</h1>
          <p className="main-objective-text">
            Pioneering digital networking for preventive environmental monitoring and smart city solutions.
          </p>
          
          {/* Objectives Grid (Replaces old list) */}
          <div className="objectives-grid">
            {objectives.map((obj, index) => (
                <div key={index} className="objective-item-card">
                    <div className="check-icon">✓</div>
                    <p style={{ margin: 0, fontSize: '0.95rem', color: '#334155', lineHeight: 1.5 }}>{obj}</p>
                </div>
            ))}
          </div>
        </section>

        {/* 2. RESEARCH & INTELLECTUAL PROPERTY */}
        <section className="mb-section">
          <h2 className="resources-section-title">Research & Intellectual Property</h2>
          
          <div className="resources-grid">
             {/* Patent Card (Unique Style) */}
             <div className="resource-card patent-card">
                <span className="card-badge patent-badge">Patent Filed</span>
                <h4 className="card-title">{patent.title}</h4>
                <div className="meta-info">
                    <p style={{margin: '0.2rem 0'}}><strong>No:</strong> {patent.appNumber}</p>
                    <p style={{margin: '0.2rem 0'}}><strong>Date:</strong> {patent.filingDate}</p>
                </div>
                <div className="card-footer" style={{ color: '#16a34a' }}>
                    ✓ {patent.status}
                </div>
             </div>

             {/* Publication Cards */}
             {publications.map((pub, idx) => (
                <div key={idx} className="resource-card publication-card">
                    <span className={`card-badge ${pub.status === 'Accepted' || pub.status === 'Published' ? 'success-badge' : 'pending-badge'}`}>
                      {pub.status}
                    </span>
                    <h4 className="card-title">{pub.title}</h4>
                    <div className="meta-info">
                        Venue: {pub.venue}
                    </div>
                    <div className="card-footer">
                        {pub.type}
                    </div>
                </div>
             ))}
          </div>
        </section>

        {/* 3. MANPOWER & WORKSHOPS TABLE */}
        <section className="mb-section">
            <h2 className="resources-section-title">Manpower Trained & Workshops</h2>
            <div className="table-responsive-container">
                <table className="modern-table">
                    <thead>
                        <tr>
                            <th>Program Title</th>
                            <th>Type</th>
                            <th>Duration</th>
                            <th>Date (2025)</th>
                            <th>Participants</th>
                        </tr>
                    </thead>
                    <tbody>
                        {trainingEvents.map((event, index) => (
                            <tr key={index}>
                                <td style={{ fontWeight: 600, color: '#1e293b' }}>{event.title}</td>
                                <td><span className="pill-type">{event.type}</span></td>
                                <td>{event.duration}</td>
                                <td>{event.date}</td>
                                <td>{event.participants}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </section>

        {/* 4. DOWNLOADS & BROCHURES */}
        <section className="mb-section">
          <h2 className="resources-section-title">Official Documents</h2>
          
          {brochures.length === 0 ? (
            <div className="brochure-grid">
                 <div className="brochure-card" style={{ opacity: 0.6 }}>
                    <p>Loading documents...</p>
                 </div>
            </div>
          ) : (
            <div className="brochure-grid">
              {brochures.map((b, idx) => (
                <div key={idx} className="brochure-card">
                  <div>
                    <span className="card-badge pending-badge" style={{ marginBottom: '0.5rem' }}>{b.category}</span>
                    <h4 style={{ fontSize: '1rem', fontWeight: 700, margin: '0.5rem 0' }}>{b.title}</h4>
                    <p style={{ fontSize: '0.9rem', color: '#64748b' }}>{b.description}</p>
                  </div>
                  <a href={b.url} target="_blank" rel="noopener noreferrer" className="download-btn">
                    <span>Download PDF</span>
                  </a>
                </div>
              ))}
            </div>
          )}
        </section>

        <div style={{ textAlign: 'center', marginTop: '4rem' }}>
          <Link to="/" style={{ color: '#64748b', fontWeight: 600, textDecoration: 'none' }}>← Back to Home</Link>
        </div>
      </div>
    </div>
  );
};

export default ResourcesPage;
